if __civmcp_diplo_fix == nil then   __civmcp_diplo_fix = function()     local pid = Game.GetLocalPlayer()     if pid == nil or pid < 0 then return end     local p = Players[pid]     if p ~= nil and p:IsTurnActive() and not g_bIsLocalPlayerTurn then       pcall(OnLocalPlayerTurnBegin)     end   end   Events.LocalPlayerChanged.Add(__civmcp_diplo_fix)   Events.PlayerTurnActivated.Add(__civmcp_diplo_fix)   __civmcp_diplo_fix()   print("DIPLOFIX|installed") else   __civmcp_diplo_fix()   print("DIPLOFIX|present") end print("---END---")